sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var gr = new GlideRecord('x_hccc_hoc_ohs_hira_case');

    gr.setWorkflow(false);
    gr.addQuery('sys_id', current.hira_case);
    gr.addEncodedQuery('stateIN952'); //Make sure the HIRA is marked as fully completed
    //Final review (Advisor) (104),	HIRA Completed - Implementing measures (951),HIRA Completed (952)
    gr.query();
    while (gr.next()) {
        gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.hira_state_changed_to_implementing_measures"));
        gr.state = 951; //Mark the HIRA record as "HIRA Completed - Implementing measures"
        gr.update();
    }

    //above could be replaced with ~
    /*if(current.hira_case.state === "952"){
		gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.hira_state_changed_to_implementing_measures"));
        current.hira_case.state = 951; //Mark the HIRA record as "HIRA Completed - Implementing measures"
		current.hira_case.update;
	}*/
})(current, previous);
